import{_ as a,c as n,o as i,j as s,Y as o,t as l}from"./chunks/framework.BNTND4LZ.js";const g=JSON.parse('{"title":"git-name-rev | x-cmd man (git man1) | Find symbolic names for given revs","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-name-rev - Find symbolic names for given revs","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-name-rev | x-cmd man (git man1) | Find symbolic names for given revs"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-name-rev - Find symbolic names for given revs"}]]},"headers":[],"params":{"isMan":true,"man":"git-name-rev","category":"git man1","desc":"Find symbolic names for given revs"},"relativePath":"git/man1/git-name-rev.md","filePath":"git/man1/[man].md"}'),r={name:"git/man1/git-name-rev.md"},h={class:"visually-hidden"};function c(t,e,p,d,m,u){return i(),n("div",null,[s("h1",h,l(t.$params.man),1),e[0]||(e[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-name-rev - Find symbolic names for given revs</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name-rev</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--tags] [--refs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ( </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--all</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --stdin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">commit-ish</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Finds symbolic names suitable for human digestion for revisions given in any format parsable by <em>git rev-parse</em>.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--tags</p><blockquote><p>Do not use branch names, but only tags to name the commits</p></blockquote><p>--refs=&lt;pattern&gt;</p><blockquote><p>Only use refs whose names match a given shell pattern. The pattern can be one of branch name, tag name or fully qualified ref name. If given multiple times, use refs whose names match any of the given shell patterns. Use <strong>--no-refs</strong> to clear any previous ref patterns given.</p></blockquote><p>--exclude=&lt;pattern&gt;</p><blockquote><p>Do not use any ref whose name matches a given shell pattern. The pattern can be one of branch name, tag name or fully qualified ref name. If given multiple times, a ref will be excluded when it matches any of the given patterns. When used together with --refs, a ref will be used as a match only when it matches at least one --refs pattern and does not match any --exclude patterns. Use <strong>--no-exclude</strong> to clear the list of exclude patterns.</p></blockquote><p>--all</p><blockquote><p>List all commits reachable from all refs</p></blockquote><p>--annotate-stdin</p><blockquote><p>Transform stdin by substituting all the 40-character SHA-1 hexes (say $hex) with &quot;$hex ($rev_name)&quot;. When used with --name-only, substitute with &quot;$rev_name&quot;, omitting $hex altogether.</p><p>For example:</p><blockquote><pre><code>$ cat sample.txt

An abbreviated revision 2ae0a9cb82 will not be substituted.
The full name after substitution is 2ae0a9cb8298185a94e5998086f380a355dd8907,
while its tree object is 70d105cc79e63b81cfdcb08a15297c23e60b07ad

$ git name-rev --annotate-stdin &lt;sample.txt

An abbreviated revision 2ae0a9cb82 will not be substituted.
The full name after substitution is 2ae0a9cb8298185a94e5998086f380a355dd8907 (master),
while its tree object is 70d105cc79e63b81cfdcb08a15297c23e60b07ad

$ git name-rev --name-only --annotate-stdin &lt;sample.txt

An abbreviated revision 2ae0a9cb82 will not be substituted.
The full name after substitution is master,
while its tree object is 70d105cc79e63b81cfdcb08a15297c23e60b07ad
</code></pre></blockquote></blockquote><p>--stdin</p><blockquote><p>This option is deprecated in favor of <em>git name-rev --annotate-stdin</em>. They are functionally equivalent.</p></blockquote><p>--name-only</p><blockquote><p>Instead of printing both the SHA-1 and the name, print only the name. If given with --tags the usual tag prefix of &quot;tags/&quot; is also omitted from the name, matching the output of <strong>git-describe</strong> more closely.</p></blockquote><p>--no-undefined</p><blockquote><p>Die with error code != 0 when a reference is undefined, instead of printing <strong>undefined</strong>.</p></blockquote><p>--always</p><blockquote><p>Show uniquely abbreviated commit object as fallback.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Given a commit, find out where it is relative to the local refs. Say somebody wrote you about that fantastic commit 33db5f4d9027a10e477ccf054b2c1ab94f74c85a. Of course, you look into the commit, but that only tells you what happened, but not the context.</p><p>Enter <em>git name-rev</em>:</p><blockquote><pre><code>% git name-rev 33db5f4d9027a10e477ccf054b2c1ab94f74c85a
33db5f4d9027a10e477ccf054b2c1ab94f74c85a tags/v0.99~940
</code></pre></blockquote><p>Now you are wiser, because you know that it happened 940 revisions before v0.99.</p><p>Another nice thing you can do is:</p><blockquote><pre><code>% git log | git name-rev --stdin
</code></pre></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,34))])}const f=a(r,[["render",c]]);export{g as __pageData,f as default};
